## ---- job array: one site per task ---------------------------------------
# number of sign permutations
num_perm <- 1:500

# Sites are independent, so this runs as an array with one site per task. One
# all-sites task needs ~100 h; per site the worst case is ~4 h, a failure costs
# one site, and a single site can be resubmitted by its task index.
# Usage: Rscript 08_gt_sign_permute.R <task_index>   (0-based)
site_list <- sort(as.integer(unique(gsub("_.*", "", colnames(hapfire)))))
args <- commandArgs(trailingOnly = TRUE)
if (length(args) < 1L) stop("expected a 0-based task index")
task <- suppressWarnings(as.integer(args[[1]]))
if (is.na(task) || task < 0L || task >= length(site_list)) {
  stop("task index ", args[[1]], " outside 0..", length(site_list) - 1L)
}
site <- site_list[task + 1L]

# per-site seed: each site draws its own sequence, and rerunning one site
# reproduces exactly that site's draws
set.seed(3000L + site)

results_dir <- paste0(
  "/global/scratch/users/milesroberts/moi_lab_projects/grenenet-phase2/results/",
  today
)
dir.create(results_dir, recursive = TRUE, showWarnings = FALSE)

output_gt_kmate_perms      <- paste0(results_dir, "/gt_perms_kmate_site", site, ".tsv")
output_var_cov_kmate_perms <- paste0(results_dir, "/var_cov_perms_kmate_site", site, ".tsv")

# delete this site's previous output: append_table() would otherwise duplicate
# every row
check_file_exists(output_gt_kmate_perms)
check_file_exists(output_var_cov_kmate_perms)

ts_message("task ", task, " of ", length(site_list) - 1L, " -> site ", site)
  print(paste("Site:", site))
  hap_site <- hapfire %>% 
    dplyr::select(starts_with(paste(site, "_", sep = "")))
  
  # garden plot numbers run to 18 and have gaps (sites 28, 55, 57), so
  # iterate the plots actually present rather than assuming 1:12
  site_plots <- sort(unique(as.integer(sub("^.*_", "", grep(paste0("^", site, "_"),
    colnames(hapfire), value = TRUE)))))
  for (exprep in site_plots) {
    print(paste("Rep:", exprep))
    hap_rep <- hap_site %>%
      dplyr::select(ends_with(paste("_", exprep, sep = ""))) %>%
      collect() %>%
      mutate(window = blocks$window) # add block ids
    #filter(row_number() %in% cls_idx) # subset to variant class
    
    # sort names to be in order of generation
    hap_rep <- hap_rep %>%
      relocate(all_of(sort(colnames(hap_rep))))
    
    if (ncol(hap_rep) < 2) {
      print("Need at least two increments. Skipping to next replicate...")
      next
    }
    
    rep_n <- grab_sample_sizes(flower_counts, pool, colnames(hap_rep), 10000, total_flowers)
    
    hap_rep <- cbind(gen0$X0_0_0, hap_rep)
    colnames(hap_rep)[1] = paste(site, "_0_", exprep, sep = "")
    
    for(p in num_perm){
      
      covmat <- covmat_from_pmat(
        pmat = hap_rep %>% select(-window),
        n = rep_n$total_flowers*2,
        correct_for_n = T,
        input_asin_trans = F,
        procedure = "window",
        windows = hap_rep %>% pull(window),
        standard_by_het = F
      )
      
      # save raw var-cov matrix
      covlong <- covmat %>%
        as.data.frame() %>%
        rownames_to_column(var = "A") %>%
        pivot_longer(cols = -A, names_to = "B", values_to = "cov")
      
      covlong$site <- site
      covlong$rep <- exprep
      covlong$class <- "smallindel_sv_snp" #paste(cls, collapse = "_")
      covlong$perm <- p
      append_table(covlong, output_var_cov_kmate_perms)
      
      gt_result <- gt_from_covmat(covmat)
      gt_result$site = site
      gt_result$rep = exprep
      gt_result$perm = p
      gt_result$class = "smallindel_sv_snp" #paste(cls, collapse = "_")
      append_table(gt_result, output_gt_kmate_perms)
      
      rm(gt_result, covmat, covlong); gc()
    }
    rm(hap_rep); gc()
  }
rm(hap_site); gc()
